// Normalize incoming lead data
const input = $('Webhook - Lead Intake').first().json;
const config = $('Set Config').first().json;

// Normalize email (lowercase, trim)
const email = (input.email || '').toLowerCase().trim();

// Split name if only fullName provided
let firstName = input.firstName || input.first_name || '';
let lastName = input.lastName || input.last_name || '';

if (!firstName && input.name) {
  const nameParts = input.name.trim().split(' ');
  firstName = nameParts[0] || '';
  lastName = nameParts.slice(1).join(' ') || '';
}

if (!firstName && input.fullName) {
  const nameParts = input.fullName.trim().split(' ');
  firstName = nameParts[0] || '';
  lastName = nameParts.slice(1).join(' ') || '';
}

// Clean phone number (remove non-digits except +)
let phone = (input.phone || input.phoneNumber || input.telephone || '').toString();
phone = phone.replace(/[^0-9+]/g, '');

// Default timezone if not provided
const timezone = input.timezone || config.timezone || 'America/New_York';

// Generate intake ID for idempotency (email + date)
const today = new Date().toISOString().split('T')[0];
const intakeId = Buffer.from(email + '-' + today).toString('base64').replace(/[^a-zA-Z0-9]/g, '').substring(0, 32);

// Extract other fields with fallbacks
const company = input.company || input.companyName || input.organization || '';
const message = input.message || input.comments || input.notes || input.inquiry || '';
const source = input.source || input.utm_source || input.referrer || 'website';
const useCase = input.useCase || input.use_case || input.interest || '';
const timeline = input.timeline || input.timeframe || input.urgency || '';
const budget = input.budget || input.budgetRange || '';
const role = input.role || input.jobTitle || input.title || input.position || '';

return {
  json: {
    // Normalized lead data
    email,
    firstName: firstName.trim(),
    lastName: lastName.trim(),
    phone,
    company,
    message,
    source,
    useCase,
    timeline,
    budget,
    role,
    timezone,
    intakeId,

    // Config passthrough
    config: config,

    // Metadata
    receivedAt: new Date().toISOString(),
    executionId: $execution.id
  }
};

// Calculate lead score based on provided data
const lead = $('Normalize Data').first().json;
const config = lead.config;

let score = 0;
let scoreBreakdown = [];

// 1. Use Case Fit (0-3 points)
const useCaseLower = (lead.useCase + ' ' + lead.message).toLowerCase();
const perfectMatchKeywords = ['automation', 'integrate', 'integration', 'workflow', 'automate', 'n8n', 'zapier'];
const goodMatchKeywords = ['efficiency', 'process', 'streamline', 'optimize', 'save time', 'manual'];
const partialMatchKeywords = ['help', 'need', 'looking for', 'interested'];

let useCaseScore = 0;
if (perfectMatchKeywords.some(kw => useCaseLower.includes(kw))) {
  useCaseScore = 3;
  scoreBreakdown.push('Use case: Perfect match (3)');
} else if (goodMatchKeywords.some(kw => useCaseLower.includes(kw))) {
  useCaseScore = 2;
  scoreBreakdown.push('Use case: Good match (2)');
} else if (partialMatchKeywords.some(kw => useCaseLower.includes(kw))) {
  useCaseScore = 1;
  scoreBreakdown.push('Use case: Partial match (1)');
} else {
  scoreBreakdown.push('Use case: No match (0)');
}
score += useCaseScore;

// 2. Timeline Urgency (0-2 points)
const timelineLower = lead.timeline.toLowerCase();
const urgentKeywords = ['immediately', 'asap', 'urgent', 'this week', 'now', 'today'];
const soonKeywords = ['this month', 'this quarter', 'soon', 'next month'];

let timelineScore = 0;
if (urgentKeywords.some(kw => timelineLower.includes(kw))) {
  timelineScore = 2;
  scoreBreakdown.push('Timeline: Urgent (2)');
} else if (soonKeywords.some(kw => timelineLower.includes(kw))) {
  timelineScore = 1;
  scoreBreakdown.push('Timeline: Soon (1)');
} else {
  scoreBreakdown.push('Timeline: Not urgent (0)');
}
score += timelineScore;

// 3. Budget Signal (0-2 points)
let budgetScore = 0;
const budgetStr = lead.budget.toString().toLowerCase();
const budgetNum = parseInt(budgetStr.replace(/[^0-9]/g, '')) || 0;

if (budgetNum >= 5000 || budgetStr.includes('10k') || budgetStr.includes('10,000')) {
  budgetScore = 2;
  scoreBreakdown.push('Budget: High (2)');
} else if (budgetNum >= 1000 || budgetStr.includes('1k') || budgetStr.includes('1,000')) {
  budgetScore = 1;
  scoreBreakdown.push('Budget: Medium (1)');
} else if (budgetStr.length > 0) {
  budgetScore = 0;
  scoreBreakdown.push('Budget: Low (0)');
} else {
  scoreBreakdown.push('Budget: Not provided (0)');
}
score += budgetScore;

// 4. Role/Seniority (0-2 points)
const roleLower = lead.role.toLowerCase();
const seniorKeywords = ['owner', 'ceo', 'cto', 'coo', 'cfo', 'founder', 'director', 'vp', 'vice president', 'head of', 'chief'];
const midKeywords = ['manager', 'lead', 'senior', 'supervisor', 'team lead'];

let roleScore = 0;
if (seniorKeywords.some(kw => roleLower.includes(kw))) {
  roleScore = 2;
  scoreBreakdown.push('Role: Senior (2)');
} else if (midKeywords.some(kw => roleLower.includes(kw))) {
  roleScore = 1;
  scoreBreakdown.push('Role: Mid-level (1)');
} else if (lead.role.length > 0) {
  roleScore = 0;
  scoreBreakdown.push('Role: Other (0)');
} else {
  scoreBreakdown.push('Role: Not provided (0)');
}
score += roleScore;

// 5. Data Completeness (0-1 point)
let completenessScore = 0;
if (lead.phone && lead.phone.length >= 10) {
  completenessScore = 1;
  scoreBreakdown.push('Phone provided (1)');
} else {
  scoreBreakdown.push('Phone not provided (0)');
}
score += completenessScore;

// Determine routing
let route = 'disqualified';
let status = 'disqualified';

if (score >= config.qualifiedMin) {
  route = 'qualified';
  status = 'qualified';
} else if (score >= config.nurtureMin) {
  route = 'nurture';
  status = 'nurture';
}

const rationale = scoreBreakdown.join(' | ');

return {
  json: {
    ...lead,
    score,
    route,
    status,
    rationale,
    scoreBreakdown
  }
};

